"""Nom base"""
from builtins import object

from taf.ul.trs_e2e_fw.lib.ems.exceptions import NomSetupFailedException
from taf.ul.trs_e2e_fw.lib.ems.nom.nom_factory import NomFactory
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class NomBase(object):
    """Nom base"""
    TOOL = 'nom'

    def __init__(self):
        self.nom_factory = NomFactory.get_instance()
        self.bts_moc_id = 'PLMN-PLMN/MRBTS-{bts_id}'.format(bts_id=get_config_variable(['bts_id']))

    def setup_ems(self, **kwargs):
        """Setup ems"""
        config_device = kwargs.get('config_device')
        tool_config = get_config_variable(['ems', config_device])
        client_id = tool_config['client_id']
        username = tool_config['username']
        password = tool_config['password']
        apigw_uri = tool_config['apigw_uri']
        user_mgmt_uri = tool_config['user_mgmt_uri']
        port = tool_config['port']
        nom_version = tool_config['nom_version']
        secure = tool_config['secure']

        try:

            nom_rf_secret = self.nom_factory.nom.register_the_client(client_id=client_id, username=username,
                                                                     password=password,
                                                                     apigw_uri=apigw_uri)

            self.nom_factory.nom.connect_to(user_mgmt_uri=user_mgmt_uri,
                                            apigw_uri=apigw_uri,
                                            client_id=client_id,
                                            client_secret=nom_rf_secret,
                                            port=port,
                                            username=username,
                                            password=password,
                                            nom_version=nom_version,
                                            secure=secure)
        except Exception as conn_e:
            raise NomSetupFailedException("Setup NOM failed Sbecause: {}".format(str(conn_e)))

    def teardown_ems(self, **kwargs):
        """Teardown ems"""
        config_device = kwargs.get('config_device')
        tool_config = get_config_variable(['ems', config_device])

        client_id = tool_config['client_id']
        username = tool_config['username']
        password = tool_config['password']
        apigw_uri = tool_config['apigw_uri']

        self.nom_factory.nom.delete_the_client(client_id, username, password, apigw_uri)
